def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    pressure_bids = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if opp.get('hp', 0) > 0 and opp.get('budget', 0) > 0:
                    pressure_bids.append(bid)

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.25))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    active_pressure = max(pressure_bids) if pressure_bids else highest_prev

    scarcity = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))
    tight_supply = supply <= 18
    very_tight_supply = supply <= 16

    urgent = hp <= 3 or no_water_days >= 2
    semi_urgent = hp <= 5 or no_water_days >= 1

    target = DAILY_SALARY * 0.45

    if urgent:
        target = max(target, DAILY_SALARY * 0.92)
    elif semi_urgent:
        target = max(target, DAILY_SALARY * 0.72)

    if very_tight_supply:
        target = max(target, active_pressure + 3.0, DAILY_SALARY * 0.82)
    elif tight_supply:
        target = max(target, active_pressure + 1.5, DAILY_SALARY * 0.62)
    else:
        if active_pressure > DAILY_SALARY * 1.2:
            target = max(target, DAILY_SALARY * 0.38)
        else:
            target = max(target, min(DAILY_SALARY * 0.6, active_pressure + 1.0))

    if budget < DAILY_SALARY * 2 and not urgent:
        target = min(target, DAILY_SALARY * 0.5)

    if hp >= 8 and no_water_days == 0 and scarcity > 0.6 and not tight_supply:
        target = min(target, DAILY_SALARY * 0.4)

    if day >= 8 and hp > 4:
        target = min(target, DAILY_SALARY * 0.58)

    bid = min(budget, target)
    if budget > 0 and urgent:
        bid = max(bid, min(budget, DAILY_SALARY * 0.9))

    return max(0.0, float(bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    # Alive opponents
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # If no opponents, take what we can afford
    if not alive_opps:
        return max(0.0, min(float(my_status.get('budget', 0.0)), DAILY_SALARY * 0.4))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # Read yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    for _, opp in alive_opps:
        pt = opp.get('previous_trace', {}) or {}
        b = pt.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many shares we likely need: if supply is tight, bid more.
    # supply is in [15,25] so integer shares are 1 or 2.
    # We target securing at least 1 unit of water requirement.
    if supply <= WATER_REQ + 1e-9:
        scarcity_factor = 1.0
    else:
        # More supply -> less urgency
        # Map supply in [15,25] to [1.0,0.6]
        scarcity_factor = 1.0 - 0.4 * ((supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY))
        if scarcity_factor < 0.6:
            scarcity_factor = 0.6
        if scarcity_factor > 1.0:
            scarcity_factor = 1.0

    # If someone previously overbid heavily, avoid matching; instead bid enough to not be starved.
    # Cindy averaged ~133 and died; David bid 0 and died; Eric survived with ~68.
    aggressive_threshold = DAILY_SALARY * 0.85  # 76.5

    # Base bid policy
    if my_hp <= 2.0:
        base = DAILY_SALARY * 0.95
    elif my_hp <= 4.0:
        base = DAILY_SALARY * 0.75
    else:
        base = DAILY_SALARY * 0.55

    # Adjust based on yesterday's max bid (proxy for opponent aggressiveness)
    if highest_prev_bid >= aggressive_threshold:
        # Don't overpay: reduce compared to base, but still scale by scarcity.
        base *= 0.85
    else:
        # If yesterday bids were calmer, slightly increase to capture share.
        base *= 1.05

    target = base * scarcity_factor

    # Budget cap
    if my_budget <= 0.0:
        return 0.0

    # Ensure non-negative and not above budget
    bid = max(0.0, min(my_budget, target))

    # Small floor to avoid bidding too low when supply is scarce
    if scarcity_factor >= 0.9 and bid < DAILY_SALARY * 0.35:
        bid = min(my_budget, DAILY_SALARY * 0.35)

    return float(bid)

